content.content:
=== emoji_burst
--- template.json
{
  "description": "Reaction burst: a pop flash at a point and a spray of emoji / pixel hearts that fly out on gravity arcs, spin and pop away.",
  "kind": "overlay",
  "duration": 1.5,
  "orientations": ["landscape", "vertical"],
  "vars": {
    "emoji":  {"type": "string", "label": "Particles, space/comma separated. Emoji, 'heart' (pixel heart), 'star' (pixel star) or short words", "default": "💀 😂 🔥 heart"},
    "x":      {"type": "number", "label": "Burst x (0-1)", "default": 0.5},
    "y":      {"type": "number", "label": "Burst y (0-1)", "default": 0.55},
    "count":  {"type": "number", "label": "Particle count", "default": 16},
    "opaque": {"type": "boolean", "label": "Opaque ink background", "default": false}
  }
}
--- markup.html
<div id="eb-wrap">
  <svg id="eb-flash" xmlns="http://www.w3.org/2000/svg"></svg>
  <div id="eb-parts"></div>
</div>
--- template.css
@font-face { font-family: "EB Emoji"; src: local("Segoe UI Emoji"), local("SegoeUIEmoji"), local("Noto Color Emoji"), local("Apple Color Emoji"); }
#eb-wrap { position: absolute; inset: 0; }
#eb-flash { position: absolute; left: 0; top: 0; overflow: visible; }
#eb-parts { position: absolute; inset: 0; }
.eb-p { position: absolute; display: flex; align-items: center; justify-content: center; line-height: 1; white-space: nowrap; }
.eb-emo {
  font-family: "EB Emoji", sans-serif;
  filter: drop-shadow(2px 0 0 #000) drop-shadow(-2px 0 0 #000) drop-shadow(0 2px 0 #000) drop-shadow(0 -2px 0 #000) drop-shadow(2px 4px 0 rgba(0,0,0,0.45));
}
.eb-word { color: var(--gold); }
.eb-px svg { filter: drop-shadow(2px 3px 0 rgba(0,0,0,0.5)); }
--- template.js
MC.define(function (S) {
  var v = S.v, d = S.d, W = d.w, H = d.h;
  var clamp = function (a, lo, hi) { return Math.max(lo, Math.min(hi, a)); };
  var cx = clamp(MC.num(v.x, 0.5), 0, 1) * W, cy = clamp(MC.num(v.y, 0.55), 0, 1) * H;
  var count = Math.round(clamp(MC.num(v.count, 16), 1, 40));
  var rnd = MC.rng(9001);

  // ---- tokens: split on spaces/commas; a run of emoji with no separators is split into graphemes
  var raw = String(v.emoji == null ? "" : v.emoji).trim() || "heart";
  var toks = [];
  raw.split(/[\s,]+/).filter(Boolean).forEach(function (t) {
    if (/^(heart|<3|star)$/i.test(t) || /^[\w!?.#'-]+$/.test(t)) { toks.push(t); return; }
    var g = [];
    try {
      if (typeof Intl !== "undefined" && Intl.Segmenter) {
        var seg = new Intl.Segmenter(undefined, { granularity: "grapheme" });
        var it = seg.segment(t)[Symbol.iterator](), n;
        while (!(n = it.next()).done) g.push(n.value.segment);
      }
    } catch (e) { g = []; }
    if (!g.length) g = Array.from(t);
    g.forEach(function (x) { if (x.trim()) toks.push(x); });
  });

  // pixel sprites (8x7 heart, 7x7 star) with a 1px ink rim
  var HEART = ["..oo.oo..", ".oRRoRRo.", "oRWRRRRRo", "oRRRRRRRo", ".oRRRRRo.", "..oRRRo..", "...oRo...", "....o...."];
  var STAR = ["....o....", "...oYo...", "oooYYYooo", "oYYYWYYYo", ".oYYYYYo.", "..oYYYo..", ".oYYoYYo.", ".oYo.oYo.", ".oo...oo."];
  var red = MC.css("--redstone") || "#FF4B4B", gold = MC.css("--gold") || "#FFCC33";
  function sprite(tok, size) {
    var heart = !/^star$/i.test(tok);
    var rows = heart ? HEART : STAR;
    var pal = heart ? { o: "#000", R: red, W: "#ffffff" } : { o: "#000", Y: gold, W: "#ffffff" };
    return MC.pixelSVG(rows, pal, size / rows[0].length);
  }

  // ---- flash: starburst rays + ring at the origin
  var svg = document.getElementById("eb-flash");
  svg.setAttribute("width", W); svg.setAttribute("height", H); svg.setAttribute("viewBox", "0 0 " + W + " " + H);
  var R = d.vertical ? 84 : 78, f = function (n) { return n.toFixed(1); };
  var star = "";
  for (var i = 0; i < 16; i++) {
    var a = (i / 16) * Math.PI * 2, rr = i % 2 ? R * 0.42 : R;
    star += (i ? " L" : "M") + f(cx + Math.cos(a) * rr) + "," + f(cy + Math.sin(a) * rr);
  }
  svg.innerHTML =
    '<g id="eb-star"><path d="' + star + ' Z" fill="' + gold + '" stroke="#000" stroke-width="5" stroke-linejoin="round"/>' +
    '<circle cx="' + f(cx) + '" cy="' + f(cy) + '" r="' + f(R * 0.3) + '" fill="#fff"/></g>' +
    '<circle id="eb-ring" cx="' + f(cx) + '" cy="' + f(cy) + '" r="' + f(R) + '" fill="none" stroke="#fff" stroke-width="7"/>';
  var starG = document.getElementById("eb-star"), ring = document.getElementById("eb-ring");

  // ---- particles
  var wrap = document.getElementById("eb-parts"), ps = [];
  var base = d.vertical ? 50 : 46, reach = d.vertical ? 270 : 260;
  for (var k = 0; k < count; k++) {
    var tok = toks[k % toks.length];
    var size = Math.round(base * (0.78 + rnd() * 0.5));
    var el = document.createElement("div");
    el.className = "eb-p";
    el.setAttribute("data-layout-allow-overlap", ""); el.setAttribute("data-layout-allow-overflow", "");
    if (/^(heart|<3|star)$/i.test(tok)) {
      el.classList.add("eb-px"); el.innerHTML = sprite(tok, size);
    } else if (/^[\w!?.#'-]+$/.test(tok)) {
      el.classList.add("eb-word", "f-caption", "mc-outline-thin");
      el.textContent = tok.toUpperCase(); size = Math.round(size * 0.62);
      el.style.fontSize = size + "px";
    } else {
      el.classList.add("eb-emo"); el.textContent = tok; el.style.fontSize = size + "px";
    }
    var bw = Math.round(size * 1.3);   // box, centred on the origin; the glyph is flex-centred inside
    el.style.width = (el.classList.contains("eb-word") ? size * tok.length * 0.7 + 10 : bw) + "px"; el.style.height = bw + "px";
    el.style.left = (cx - parseFloat(el.style.width) / 2) + "px"; el.style.top = (cy - bw / 2) + "px";
    wrap.appendChild(el);
    // fan mostly upward (-170..-10 deg), a few sideways/down
    var ang = -Math.PI * (0.06 + 0.88 * ((k + rnd() * 0.8) / count));
    if (k % 5 === 4) ang = (rnd() < 0.5 ? -0.05 : -Math.PI + 0.05) + (rnd() - 0.5) * 0.6;
    var dist = reach * (0.55 + rnd() * 0.55);
    ps.push({ el: el, dx: Math.cos(ang) * dist, up: Math.sin(ang) * dist, fall: reach * (0.35 + rnd() * 0.35),
      rot: (rnd() - 0.5) * 220, delay: rnd() * 0.08, life: 0.95 + rnd() * 0.3 });
  }

  // ---- timeline
  var tl = gsap.timeline({ paused: true });
  tl.fromTo(starG, { scale: 0, rotation: -30, svgOrigin: cx + " " + cy, opacity: 1 }, { scale: 1.15, rotation: 0, duration: 0.14, ease: "back.out(3)" }, 0);
  tl.to(starG, { scale: 0.2, opacity: 0, duration: 0.18, ease: "power2.in" }, 0.16);
  tl.fromTo(ring, { scale: 0.3, opacity: 1, svgOrigin: cx + " " + cy }, { scale: 2.3, opacity: 0, duration: 0.42, ease: "power2.out" }, 0.04);
  tl.set(ps.map(function (p) { return p.el; }), { scale: 0 }, 0);
  ps.forEach(function (p) {
    var t0 = 0.04 + p.delay, up = Math.min(p.up, -10) * 1.0;
    tl.fromTo(p.el, { x: 0, rotation: 0 }, { x: p.dx, rotation: p.rot, duration: p.life, ease: "power2.out", immediateRender: false }, t0);
    tl.fromTo(p.el, { scale: 0 }, { keyframes: [{ scale: 1.3, duration: 0.14, ease: "back.out(3)" }, { scale: 1, duration: 0.12, ease: "power1.out" }], immediateRender: false }, t0);
    tl.fromTo(p.el, { y: 0 }, { y: up, duration: p.life * 0.42, ease: "power2.out", immediateRender: false }, t0);
    tl.to(p.el, { y: up + p.fall, duration: p.life * 0.58, ease: "power2.in" }, t0 + p.life * 0.42);
    tl.to(p.el, { scale: 0, duration: 0.16, ease: "back.in(2.4)" }, Math.min(t0 + p.life - 0.06, d.duration - 0.18));
  });
  return tl;
});
=== lower_third
--- template.json
{
  "description": "Name tag / label: beveled icon block pops in, name bar extends from it, sub-label tag slides under. Lower-left.",
  "kind": "overlay",
  "duration": 3,
  "stretchable": true,
  "min_duration": 1.4,
  "orientations": ["landscape", "vertical"],
  "vars": {
    "text":   {"type": "string", "label": "Name / label", "default": "STEVE"},
    "sub":    {"type": "string", "label": "Sub-label (optional)", "default": "PROFESSIONAL CAVE GOBLIN"},
    "icon":   {"type": "string", "label": "Icon glyph (default: first letter)", "default": ""},
    "accent": {"type": "color", "label": "Icon colour", "brand": "colors.grass"},
    "opaque": {"type": "boolean", "label": "Opaque ink background", "default": false}
  }
}
--- markup.html
<div id="lt-group">
  <div id="lt-barwrap"><div id="lt-bar" class="mc-panel"><div id="lt-name" class="f-display">STEVE</div></div></div>
  <div id="lt-subwrap"><div id="lt-sub" class="f-ui-bold">PROFESSIONAL CAVE GOBLIN</div></div>
  <div id="lt-icon" class="mc-block"><div id="lt-glyph" class="f-display mc-outline-thin">S</div></div>
</div>
--- template.css
#lt-group { position: absolute; }
#lt-icon { position: absolute; left: 0; top: 0; --bc: var(--accent); border-width: 3px;
  display: flex; align-items: center; justify-content: center; box-shadow: inset 5px 5px 0 rgba(255,255,255,0.3), inset -5px -5px 0 rgba(0,0,0,0.3), 5px 6px 0 rgba(0,0,0,0.45); }
#lt-icon::after { display: none; }
#lt-glyph { color: var(--paper); line-height: 1; position: relative; top: 0.06em; }
#lt-barwrap { position: absolute; overflow: hidden; padding: 0 10px 10px 0; }
#lt-bar { display: inline-block; white-space: nowrap; border-left-width: 0; }
#lt-name { color: var(--paper); line-height: 1; position: relative; top: 0.08em; }
#lt-subwrap { position: absolute; overflow: hidden; padding: 0 8px 8px 0; }
#lt-sub {
  display: inline-block; background: var(--paper); color: var(--ink); white-space: nowrap; line-height: 1;
  border: 3px solid #000; box-shadow: 4px 4px 0 #000;
}
--- template.js
MC.define(function (S) {
  var v = S.v, d = S.d, W = d.w, H = d.h;
  var text = String(v.text || "").toUpperCase();
  var sub = String(v.sub || "").trim().toUpperCase();
  var glyph = String(v.icon || "").trim() || MC.plain(text).replace(/[^A-Z0-9]/g, "").charAt(0) || "!";

  var ICON = d.vertical ? 104 : 92;
  var nameSize = Math.floor(Math.min(d.vertical ? 50 : 50, (W * (d.vertical ? 0.6 : 0.5)) / (Math.max(text.length, 1) * 0.53)));
  var barH = Math.round(nameSize * 1.45);
  var subSize = Math.floor(Math.min(d.vertical ? 22 : 21, (W * (d.vertical ? 0.68 : 0.5)) / (Math.max(sub.length, 1) * 0.62)));

  var g = document.getElementById("lt-group");
  g.style.left = (d.vertical ? 26 : 36) + "px";
  g.style.top = (d.vertical ? H * 0.66 : H - ICON - 64) + "px";

  var icon = document.getElementById("lt-icon");
  icon.style.width = ICON + "px"; icon.style.height = ICON + "px";
  var gl = document.getElementById("lt-glyph");
  gl.textContent = glyph.toUpperCase();
  gl.style.fontSize = Math.round(ICON * (glyph.length > 1 ? 0.42 : 0.62)) + "px";

  var bw = document.getElementById("lt-barwrap"), bar = document.getElementById("lt-bar");
  bw.style.left = (ICON - 6) + "px";
  bw.style.top = Math.round((ICON - barH) / 2 - (sub ? 12 : 0)) + "px";
  bar.style.height = barH + "px";
  bar.style.padding = "0 " + Math.round(nameSize * 0.6) + "px 0 " + Math.round(nameSize * 0.55 + 6) + "px";
  bar.style.display = "flex"; bar.style.alignItems = "center";
  var nm = document.getElementById("lt-name");
  nm.textContent = text; nm.style.fontSize = nameSize + "px";

  var sw = document.getElementById("lt-subwrap"), sEl = document.getElementById("lt-sub");
  if (sub) {
    sEl.textContent = sub; sEl.style.fontSize = subSize + "px";
    sEl.style.padding = Math.round(subSize * 0.4) + "px " + Math.round(subSize * 0.6) + "px " + Math.round(subSize * 0.3) + "px";
    sw.style.left = (ICON + 10) + "px";
    sw.style.top = (parseFloat(bw.style.top) + barH + 4) + "px";
  } else {
    sw.style.display = "none";
  }

  var tl = gsap.timeline({ paused: true });
  tl.fromTo(icon, { scale: 0, rotation: -120 }, { scale: 1, rotation: 0, duration: 0.34, ease: "back.out(2.4)" }, 0);
  tl.fromTo(bar, { xPercent: -101 }, { xPercent: 0, duration: 0.32, ease: "power4.out" }, 0.16);
  tl.fromTo(nm, { y: barH }, { y: 0, duration: 0.26, ease: "back.out(2)" }, 0.3);
  if (sub) tl.fromTo(sEl, { yPercent: -140 }, { yPercent: 0, duration: 0.26, ease: "back.out(2)" }, 0.44);
  // icon "hop" accent once settled
  tl.to(icon, { keyframes: [{ y: -10, rotation: -8, duration: 0.12, ease: "power2.out" }, { y: 0, rotation: 0, duration: 0.2, ease: "bounce.out" }] }, 0.8);
  // exit
  var out = d.duration - 0.42;
  if (sub) tl.to(sEl, { yPercent: -140, duration: 0.16, ease: "power2.in" }, out);
  tl.to(nm, { y: -barH, duration: 0.16, ease: "power2.in" }, out + 0.04);
  tl.to(bar, { xPercent: -101, duration: 0.22, ease: "power3.in" }, out + 0.1);
  tl.to(icon, { scale: 0, rotation: 120, duration: 0.2, ease: "back.in(2)" }, out + 0.22);
  return tl;
});
=== advancement_toast
--- template.json
{
  "description": "Minecraft advancement toast (\"Advancement Made!\" / \"Goal Reached!\" / \"Challenge Complete!\") sliding in at the top-right with an item icon.",
  "kind": "overlay",
  "duration": 3,
  "orientations": ["landscape", "vertical"],
  "vars": {
    "title":    {"type": "string", "label": "Advancement name", "default": "Diamonds!"},
    "subtitle": {"type": "string", "label": "Description line (empty = none, like vanilla)", "default": ""},
    "kind":     {"type": "string", "label": "task | goal | challenge (sets header text and colour)", "default": "task"},
    "header":   {"type": "string", "label": "Header override (empty = from kind)", "default": ""},
    "icon":     {"type": "string", "label": "Icon PNG as a data:image/png;base64 URI or http(s) URL (local file paths cannot load; empty = pixel diamond)", "default": ""},
    "opaque":   {"type": "boolean", "label": "Opaque ink background", "default": false}
  }
}
--- markup.html
<div id="at-toast">
  <div id="at-frame"></div>
  <div id="at-slot"><div id="at-icon"></div></div>
  <div id="at-head" class="f-ui at-txt">Advancement Made!</div>
  <div id="at-name" class="f-ui at-txt">Diamonds!</div>
  <div id="at-desc" class="f-ui at-txt"></div>
  <div id="at-sparks"></div>
</div>
--- template.css
/* Advancement toast. Sizes are set in template.js in GUI pixels (--p). */
#at-toast { position: absolute; left: 0; top: 0; }
#at-frame {
  position: absolute; inset: 0;
  background: #212121;
  /* stepped 1-gui-pixel corners like the vanilla toast sprite */
  clip-path: polygon(var(--p) 0, calc(100% - var(--p)) 0, calc(100% - var(--p)) var(--p), 100% var(--p),
    100% calc(100% - var(--p)), calc(100% - var(--p)) calc(100% - var(--p)), calc(100% - var(--p)) 100%,
    var(--p) 100%, var(--p) calc(100% - var(--p)), 0 calc(100% - var(--p)), 0 var(--p), var(--p) var(--p));
  box-shadow:
    inset 0 0 0 var(--p) var(--rim),
    inset 0 0 0 calc(var(--p) * 2) #0b0b0b;
}
#at-slot {
  position: absolute;
  background: #8b8b8b;
  box-shadow: inset var(--p) var(--p) 0 #373737, inset calc(var(--p) * -1) calc(var(--p) * -1) 0 #ffffff;
}
#at-icon { position: absolute; image-rendering: pixelated; }
#at-icon img, #at-icon svg { display: block; width: 100%; height: 100%; image-rendering: pixelated; }
.at-txt { position: absolute; white-space: nowrap; line-height: 1; -webkit-font-smoothing: none; }
#at-sparks { position: absolute; inset: 0; pointer-events: none; }
.at-spark { position: absolute; }
--- template.js
MC.define(function (S) {
  var v = S.v, d = S.d, W = d.w, H = d.h;
  var rnd = MC.rng(7);
  /* Minecraft font: 1 font pixel = size/10. Vanilla text shadow = 1 font pixel down-right at colour >> 2. */
  function mcText(el, text, size, color) {
    el.textContent = text; el.style.fontSize = size + "px"; el.style.color = color;
    el.style.textShadow = (size / 10) + "px " + (size / 10) + "px 0 " + MC.shade(color, -0.75);
  }
  /* Text width from the Minecraft Regular advance table (font px; 1 font px = size/10). */
  var ADV = { 2: "!,.:;i|", 3: "'l", 4: " I[]t", 5: "\"()*<>fk{}", 7: "@~" };
  function mcWidth(t, size) {
    var w = 0;
    for (var i = 0; i < t.length; i++) {
      var c = t.charAt(i), a = 6;
      for (var k in ADV) if (ADV[k].indexOf(c) >= 0) { a = +k; break; }
      w += a;
    }
    return w * size / 10;
  }

  var kind = String(v.kind || "task").toLowerCase();
  var KINDS = {
    task:      { head: "Advancement Made!",   color: "#FFFF55", rim: "#5a5a5a" },
    goal:      { head: "Goal Reached!",       color: "#FFFF55", rim: "#6b6b52" },
    challenge: { head: "Challenge Complete!", color: "#FF55FF", rim: "#7a3f86" }
  };
  var K0 = KINDS[kind] || KINDS.task;
  var head = String(v.header || "").trim() || K0.head;
  var name = String(v.title == null ? "" : v.title).trim();
  var desc = String(v.subtitle == null ? "" : v.subtitle).trim();

  // GUI pixel size on the logical canvas (vanilla toast = 160x32 gui px)
  var p = d.vertical ? 2.5 : 2;
  var fs = 10 * p; // text at exactly 1 font px per gui px
  var textX = 30 * p, maxW = (d.vertical ? W - 32 : W * 0.6);
  var longest = Math.max(mcWidth(head, fs), mcWidth(name, fs), mcWidth(desc, fs * 0.9));
  var needW = textX + longest + 8 * p;
  var tw = Math.max(160 * p, Math.min(maxW, needW));
  var scaleText = needW > maxW ? (maxW - textX - 8 * p) / longest : 1;
  var fsT = fs * scaleText;
  var th = (desc ? 42 : 32) * p;

  var toast = document.getElementById("at-toast");
  toast.style.setProperty("--p", p + "px");
  toast.style.setProperty("--rim", K0.rim);
  toast.style.width = tw + "px"; toast.style.height = th + "px";
  var margin = d.vertical ? 16 : 14;
  var top = d.vertical ? Math.round(H * 0.105) : 14; // vertical: clear of the Shorts header
  var left = Math.round(W - margin - tw);
  toast.style.left = left + "px"; toast.style.top = top + "px";

  var slot = document.getElementById("at-slot");
  var sy = Math.round((th - 18 * p) / 2);
  slot.style.left = (7 * p) + "px"; slot.style.top = sy + "px";
  slot.style.width = (18 * p) + "px"; slot.style.height = (18 * p) + "px";
  var icon = document.getElementById("at-icon");
  icon.style.left = p + "px"; icon.style.top = p + "px";
  icon.style.width = (16 * p) + "px"; icon.style.height = (16 * p) + "px";

  var src = String(v.icon || "").trim();
  // The page is served over http, so bare local paths can't load: only data: / http(s): URIs work.
  if (src && !/^(data:|https?:)/i.test(src)) { console.warn("advancement_toast: icon must be a data: or http(s) URI; using the default diamond"); src = ""; }
  if (src) {
